/*
 * Loads the "LIMIT/EVA" (Great Gospel) resource package and model definitions.
 */
// FUNCTION: FF7 0x004739e0
void __cdecl BattleFx_LimitLoadResGreatGospel(void)
{
    char pathScratch[200];
    GfxModelTableBank *context;
    GfxResourceRequest requestRecord;
    int kind;
    GfxResourceRequest *pReq;
    int resourceRows;

    if (g_pBattle3dScene != 0 && g_pYasuiLimitGreatGospelModelTable == 0) {
        kind = 7;
        resourceRows = (int)&g_YasuiLimitGreatGospelResourceDef;
        context = (GfxModelTableBank *)(g_pBattle3dScene->modelTableBank);
        pReq = &requestRecord;
        Gfx_InitResourceRequest(pReq);
        pReq->groupTag = 0;
        // STRING: FF7 0x007f3848
        pReq->resourcePath = (char *)BattleFx_BuildResourcePath("LIMIT/EVA", pathScratch);
        Gfx_LoadModelTableIfAbsent(kind, resourceRows, pReq, &g_pYasuiLimitGreatGospelModelTable, context);
    }
}

/*
 * Entry point for Great Gospel limit effect; loads resources, transforms vertices, and begins effect.
 */
// FUNCTION: FF7 0x00473a70
int __cdecl BattleFx_LimitEnterGreatGospel(int targetMask, int actorIdx)
{
    int val;

    BattleFx_LimitLoadResGreatGospel();
    g_YasuiLimitGreatGospelModelMatrix.t[2] = 0;
    g_YasuiLimitGreatGospelModelMatrix.t[1] = g_YasuiLimitGreatGospelModelMatrix.t[2];
    g_YasuiLimitGreatGospelModelMatrix.t[0] = g_YasuiLimitGreatGospelModelMatrix.t[1];
    g_YasuiLimitGreatGospelModelAngleZ = 0;
    ((BattleFxTimelineState *)&g_YasuiLimitGreatGospelModelAngles)->wheelAngle = g_YasuiLimitGreatGospelModelAngleZ;
    *(short *)&g_YasuiLimitGreatGospelModelAngles = ((BattleFxTimelineState *)&g_YasuiLimitGreatGospelModelAngles)->wheelAngle;
    g_YasuiLimitGreatGospelTargetMask = 0;
    g_YasuiLimitGreatGospelWideFadeAngle = 0;
    g_YasuiLimitGreatGospelDrawListHead = Gfx_GetPsxPacketScratchPtr();
    g_YasuiLimitGreatGospelCameraEyeY = 0;
    val = Gfx_ModelTableGetRenderObject(0, g_pYasuiLimitGreatGospelModelTable);
    if (val != 0) {
        Gfx_ForEachPolygonSetPart((DxGroupPartCallback)BattleFx_GreatGospelCopyPolygonSetVertices, *(int *)(val + 4));
    }
    BattleFx_GreatGospelBeginEffect(targetMask, actorIdx);
    return 0;
}

/*
 * Copies polygon set vertices from model data to destination float buffer.
 */
// FUNCTION: FF7 0x00473b28
void __cdecl BattleFx_GreatGospelCopyPolygonSetVertices(int vertexIdx, int unused, BattleFxGreatGospelPolygonVertex2 *outVertices)
{
    int vertexBase;
    Vec3sPacked *vert;
    int vx;
    int vy;
    int vz;

    vertexBase = g_YasuiLimitGreatGospelPolygonMeshPointers[g_YasuiLimitGreatGospelCameraEyeY];
    vert = (Vec3sPacked *)(vertexBase + vertexIdx * 8);
    vx = vert->vx;
    outVertices->r = vx;
    vy = vert->vy;
    outVertices->s = vy;
    vz = vert->vz;
    outVertices->t = vz;
}

/*
 * Initializes effect state, rotation matrix, particle pool, camera script, and timeline tasks.
 */
// FUNCTION: FF7 0x00473b84
void __cdecl BattleFx_GreatGospelBeginEffect(int targetMask, int actorIdx)
{
    int val[2];

    Battle_AllocateResourceSlot(BattleFx_GreatGospelClearEffectFlagTask);
    Battle_GetActorMaskCentroid(g_YasuiLimitGreatGospelEffectTargetMask = targetMask, (short *)val);
    ((BattleFxTimelineState *)&g_YasuiLimitGreatGospelModelAngles)->wheelAngle = g_BattleActorRecords[actorIdx].yaw + 0x800;
    RotMatrix((SVECTOR *)&g_YasuiLimitGreatGospelModelAngles, (int *)&g_YasuiLimitGreatGospelModelMatrix);
    g_YasuiLimitGreatGospelModelMatrix.t[0] = g_BattleActorRecords[actorIdx].posX;
    g_YasuiLimitGreatGospelModelMatrix.t[2] = g_BattleActorRecords[actorIdx].posZ;
    BattleFx_GreatGospelClearParticleTable();
    Battle_AllocateResourceSlot(BattleFx_GreatGospelParticlePoolTask);
    if ((rand() & 0x100) != 0) {
        BattleFx_GreatGospelSpawnCameraScript(&g_YasuiLimitGreatGospelCameraScript1, (int)&g_YasuiLimitGreatGospelModelMatrix, actorIdx);
    } else {
        BattleFx_GreatGospelSpawnCameraScript(&g_YasuiLimitGreatGospelCameraScript2, (int)&g_YasuiLimitGreatGospelModelMatrix, actorIdx);
    }
    Battle_AllocateResourceSlot(BattleFx_GreatGospelTimelineTask);
    g_BattleScriptEffectFlag = 1;
    g_BattleStageHideFlags |= 8;
}

/*
 * Allocates task slot for camera script playback.
 */
// FUNCTION: FF7 0x00473c82
void __cdecl BattleFx_GreatGospelSpawnCameraScript(void *scriptData, int matrixPtr, int actorIdx)
{
    BattleFxGreatGospelCameraSlot *slot;

    slot = (BattleFxGreatGospelCameraSlot *)BATTLE_NEW_TASK_SLOT(BattleFx_GreatGospelRunCameraScript);
    slot->scriptData = (int)scriptData;
    slot->matrixPtr = matrixPtr;
    slot->actorIdx = actorIdx;
}

/*
 * Interprets and executes camera script commands for camera eye and focus interpolation.
 */
// FUNCTION: FF7 0x00473cc2
void __cdecl BattleFx_GreatGospelRunCameraScript(void)
{
    /* VC5 hash order fixes the slots: p=easing, q=wide vector, r=task,
       s=transform flags, t=track index, u/w=scratch vectors. v and x retain
       the original unused frame space (v is the easing-loop index in the
       nine-command dialect). The opcode i follows that space. */
    CameraScriptTask *taskPtr;
    int *wideVec;
    int easedVal;
    CameraScriptVector *scratchVector;
    int trackIdx;
    int bits;
    CameraScriptVector *vecB;
    int easeIdx;
    int x[64];
    short opcode;

    taskPtr = (CameraScriptTask *)BATTLE_CURRENT_TASK_SLOT;
    scratchVector = (CameraScriptVector *)Gfx_GetPsxScratchpadPtr(0);
    vecB = scratchVector + 1;
    wideVec = (int *)(vecB + 1);
    if (g_BattleIsPaused == 0) {
        if (taskPtr->initialized == 0) {
            g_YasuiLimitGreatGospelCameraEye.frames = 0;
            g_BattleLimitGreatGospelCameraFocus.frames = 0;
            g_YasuiLimitGreatGospelCameraEye.actor = -1;
            g_BattleLimitGreatGospelCameraFocus.actor = -1;
            taskPtr->initialized = 1;
        }
        while (g_YasuiLimitGreatGospelCameraEye.frames == 0 || g_BattleLimitGreatGospelCameraFocus.frames == 0) {
            opcode = *taskPtr->cursor++;
            if (opcode & 0x40) {
                g_pYasuiLimitGreatGospelCameraTrack = &g_YasuiLimitGreatGospelCameraEye;
                g_pYasuiLimitGreatGospelCameraOther = &g_BattleLimitGreatGospelCameraFocus;
            } else {
                g_pYasuiLimitGreatGospelCameraTrack = &g_BattleLimitGreatGospelCameraFocus;
                g_pYasuiLimitGreatGospelCameraOther = &g_YasuiLimitGreatGospelCameraEye;
            }
            g_pYasuiLimitGreatGospelCameraTrack->mode = opcode & ~0xc0;
            switch (g_pYasuiLimitGreatGospelCameraTrack->mode) {
            case SUMMON_CAMERA_WAIT:
                g_pYasuiLimitGreatGospelCameraTrack->frames = BattleFx_GreatGospelReadCameraScriptOperand(&taskPtr->cursor);
                break;
            case SUMMON_CAMERA_SET_POSITION:
                g_pYasuiLimitGreatGospelCameraTrack->position.x = *taskPtr->cursor++;
                g_pYasuiLimitGreatGospelCameraTrack->position.y = *taskPtr->cursor++;
                g_pYasuiLimitGreatGospelCameraTrack->position.z = *taskPtr->cursor++;
                break;
            case SUMMON_CAMERA_MOVE_LINEAR:
                g_pYasuiLimitGreatGospelCameraTrack->frames = BattleFx_GreatGospelReadCameraScriptOperand(&taskPtr->cursor);
                g_pYasuiLimitGreatGospelCameraTrack->velocity.x = (*taskPtr->cursor++ - g_pYasuiLimitGreatGospelCameraTrack->position.x) / g_pYasuiLimitGreatGospelCameraTrack->frames;
                g_pYasuiLimitGreatGospelCameraTrack->velocity.y = (*taskPtr->cursor++ - g_pYasuiLimitGreatGospelCameraTrack->position.y) / g_pYasuiLimitGreatGospelCameraTrack->frames;
                g_pYasuiLimitGreatGospelCameraTrack->velocity.z = (*taskPtr->cursor++ - g_pYasuiLimitGreatGospelCameraTrack->position.z) / g_pYasuiLimitGreatGospelCameraTrack->frames;
                break;
            case SUMMON_CAMERA_MOVE_ORBIT:
                scratchVector->x = g_pYasuiLimitGreatGospelCameraOther->position.x - g_pYasuiLimitGreatGospelCameraTrack->position.x;
                scratchVector->y = g_pYasuiLimitGreatGospelCameraOther->position.y - g_pYasuiLimitGreatGospelCameraTrack->position.y;
                scratchVector->z = g_pYasuiLimitGreatGospelCameraOther->position.z - g_pYasuiLimitGreatGospelCameraTrack->position.z;
                g_pYasuiLimitGreatGospelCameraTrack->distance = SqrtToInt(scratchVector->x * scratchVector->x + scratchVector->y * scratchVector->y + scratchVector->z * scratchVector->z);
                g_pYasuiLimitGreatGospelCameraTrack->base = g_pYasuiLimitGreatGospelCameraTrack->position;
                g_pYasuiLimitGreatGospelCameraTrack->frames = BattleFx_GreatGospelReadCameraScriptOperand(&taskPtr->cursor);
                scratchVector->x = *taskPtr->cursor++;
                scratchVector->y = *taskPtr->cursor++;
                scratchVector->z = *taskPtr->cursor++;
                g_pYasuiLimitGreatGospelCameraTrack->velocity.x = (scratchVector->x - g_pYasuiLimitGreatGospelCameraTrack->position.x) / g_pYasuiLimitGreatGospelCameraTrack->frames;
                g_pYasuiLimitGreatGospelCameraTrack->velocity.y = (scratchVector->y - g_pYasuiLimitGreatGospelCameraTrack->position.y) / g_pYasuiLimitGreatGospelCameraTrack->frames;
                g_pYasuiLimitGreatGospelCameraTrack->velocity.z = (scratchVector->z - g_pYasuiLimitGreatGospelCameraTrack->position.z) / g_pYasuiLimitGreatGospelCameraTrack->frames;
                switch (g_pYasuiLimitGreatGospelCameraOther->mode) {
                case SUMMON_CAMERA_MOVE_LINEAR:
                    vecB->x = g_pYasuiLimitGreatGospelCameraOther->position.x + g_pYasuiLimitGreatGospelCameraOther->velocity.x * g_pYasuiLimitGreatGospelCameraOther->frames;
                    vecB->y = g_pYasuiLimitGreatGospelCameraOther->position.y + g_pYasuiLimitGreatGospelCameraOther->velocity.y * g_pYasuiLimitGreatGospelCameraOther->frames;
                    vecB->z = g_pYasuiLimitGreatGospelCameraOther->position.z + g_pYasuiLimitGreatGospelCameraOther->velocity.z * g_pYasuiLimitGreatGospelCameraOther->frames;
                    break;
                default:
                    vecB->x = g_pYasuiLimitGreatGospelCameraOther->position.x;
                    vecB->y = g_pYasuiLimitGreatGospelCameraOther->position.y;
                    vecB->z = g_pYasuiLimitGreatGospelCameraOther->position.z;
                    break;
                }
                scratchVector->x -= vecB->x;
                scratchVector->y -= vecB->y;
                scratchVector->z -= vecB->z;
                g_pYasuiLimitGreatGospelCameraTrack->delta = (SqrtToInt(scratchVector->x * scratchVector->x + scratchVector->y * scratchVector->y + scratchVector->z * scratchVector->z) - g_pYasuiLimitGreatGospelCameraTrack->distance) / g_pYasuiLimitGreatGospelCameraTrack->frames;
                break;
            case SUMMON_CAMERA_MOVE_ACCEL:
                g_pYasuiLimitGreatGospelCameraTrack->frames = BattleFx_GreatGospelReadCameraScriptOperand(&taskPtr->cursor);
                scratchVector->x = *taskPtr->cursor++ - g_pYasuiLimitGreatGospelCameraTrack->position.x;
                scratchVector->y = *taskPtr->cursor++ - g_pYasuiLimitGreatGospelCameraTrack->position.y;
                scratchVector->z = *taskPtr->cursor++ - g_pYasuiLimitGreatGospelCameraTrack->position.z;
                g_pYasuiLimitGreatGospelCameraTrack->base.x = ((scratchVector->x - g_pYasuiLimitGreatGospelCameraTrack->velocity.x * g_pYasuiLimitGreatGospelCameraTrack->frames) * 2) / (g_pYasuiLimitGreatGospelCameraTrack->frames * g_pYasuiLimitGreatGospelCameraTrack->frames);
                g_pYasuiLimitGreatGospelCameraTrack->base.y = ((scratchVector->y - g_pYasuiLimitGreatGospelCameraTrack->velocity.y * g_pYasuiLimitGreatGospelCameraTrack->frames) * 2) / (g_pYasuiLimitGreatGospelCameraTrack->frames * g_pYasuiLimitGreatGospelCameraTrack->frames);
                g_pYasuiLimitGreatGospelCameraTrack->base.z = ((scratchVector->z - g_pYasuiLimitGreatGospelCameraTrack->velocity.z * g_pYasuiLimitGreatGospelCameraTrack->frames) * 2) / (g_pYasuiLimitGreatGospelCameraTrack->frames * g_pYasuiLimitGreatGospelCameraTrack->frames);
                break;
            case SUMMON_CAMERA_MOVE_EASED:
                g_pYasuiLimitGreatGospelCameraTrack->frames = BattleFx_GreatGospelReadCameraScriptOperand(&taskPtr->cursor);
                g_pYasuiLimitGreatGospelCameraTrack->easing = *taskPtr->cursor++;
                g_pYasuiLimitGreatGospelCameraTrack->distance = 0;
                g_pYasuiLimitGreatGospelCameraTrack->delta = 0x1000 / g_pYasuiLimitGreatGospelCameraTrack->frames;
                g_pYasuiLimitGreatGospelCameraTrack->base.x = g_pYasuiLimitGreatGospelCameraTrack->position.x;
                g_pYasuiLimitGreatGospelCameraTrack->base.y = g_pYasuiLimitGreatGospelCameraTrack->position.y;
                g_pYasuiLimitGreatGospelCameraTrack->base.z = g_pYasuiLimitGreatGospelCameraTrack->position.z;
                g_pYasuiLimitGreatGospelCameraTrack->velocity.x = *taskPtr->cursor++ - g_pYasuiLimitGreatGospelCameraTrack->position.x;
                g_pYasuiLimitGreatGospelCameraTrack->velocity.y = *taskPtr->cursor++ - g_pYasuiLimitGreatGospelCameraTrack->position.y;
                g_pYasuiLimitGreatGospelCameraTrack->velocity.z = *taskPtr->cursor++ - g_pYasuiLimitGreatGospelCameraTrack->position.z;
                break;
            case SUMMON_CAMERA_ATTACH_BONE:
                if ((g_pYasuiLimitGreatGospelCameraTrack->actor = *taskPtr->cursor++) == 0)
                    g_pYasuiLimitGreatGospelCameraTrack->actor = taskPtr->actor;
                g_pYasuiLimitGreatGospelCameraTrack->bone = *taskPtr->cursor++;
                break;
            case SUMMON_CAMERA_DETACH:
                g_pYasuiLimitGreatGospelCameraTrack->actor = -1;
                break;
            case SUMMON_CAMERA_HOLD_OUTPUT:
                g_pYasuiLimitGreatGospelCameraTrack->frames = BattleFx_GreatGospelReadCameraScriptOperand(&taskPtr->cursor);
                break;
            default:
                taskPtr->active = -1;
                return;
            }
        }
        g_pYasuiLimitGreatGospelCameraTrack = &g_YasuiLimitGreatGospelCameraEye;
        g_pYasuiLimitGreatGospelCameraOther = &g_BattleLimitGreatGospelCameraFocus;
        for (trackIdx = 0; trackIdx < 2; trackIdx++) {
            switch (g_pYasuiLimitGreatGospelCameraTrack->mode) {
            case SUMMON_CAMERA_WAIT:
                break;
            case SUMMON_CAMERA_MOVE_ACCEL:
                g_pYasuiLimitGreatGospelCameraTrack->velocity.x += g_pYasuiLimitGreatGospelCameraTrack->base.x;
                g_pYasuiLimitGreatGospelCameraTrack->velocity.y += g_pYasuiLimitGreatGospelCameraTrack->base.y;
                g_pYasuiLimitGreatGospelCameraTrack->velocity.z += g_pYasuiLimitGreatGospelCameraTrack->base.z;
            case SUMMON_CAMERA_MOVE_LINEAR:
                g_pYasuiLimitGreatGospelCameraTrack->position.x += g_pYasuiLimitGreatGospelCameraTrack->velocity.x;
                g_pYasuiLimitGreatGospelCameraTrack->position.y += g_pYasuiLimitGreatGospelCameraTrack->velocity.y;
                g_pYasuiLimitGreatGospelCameraTrack->position.z += g_pYasuiLimitGreatGospelCameraTrack->velocity.z;
                break;
            case SUMMON_CAMERA_MOVE_ORBIT:
                g_pYasuiLimitGreatGospelCameraTrack->base.x += g_pYasuiLimitGreatGospelCameraTrack->velocity.x;
                g_pYasuiLimitGreatGospelCameraTrack->base.y += g_pYasuiLimitGreatGospelCameraTrack->velocity.y;
                g_pYasuiLimitGreatGospelCameraTrack->base.z += g_pYasuiLimitGreatGospelCameraTrack->velocity.z;
                g_pYasuiLimitGreatGospelCameraTrack->distance += g_pYasuiLimitGreatGospelCameraTrack->delta;
                wideVec[0] = g_pYasuiLimitGreatGospelCameraOther->position.x - g_pYasuiLimitGreatGospelCameraTrack->base.x;
                wideVec[1] = g_pYasuiLimitGreatGospelCameraOther->position.y - g_pYasuiLimitGreatGospelCameraTrack->base.y;
                wideVec[2] = g_pYasuiLimitGreatGospelCameraOther->position.z - g_pYasuiLimitGreatGospelCameraTrack->base.z;
                VectorNormalToSVector(wideVec, (short *)scratchVector);
                g_pYasuiLimitGreatGospelCameraTrack->position.x = g_pYasuiLimitGreatGospelCameraOther->position.x - ((scratchVector->x * g_pYasuiLimitGreatGospelCameraTrack->distance) >> 12);
                g_pYasuiLimitGreatGospelCameraTrack->position.y = g_pYasuiLimitGreatGospelCameraOther->position.y - ((scratchVector->y * g_pYasuiLimitGreatGospelCameraTrack->distance) >> 12);
                g_pYasuiLimitGreatGospelCameraTrack->position.z = g_pYasuiLimitGreatGospelCameraOther->position.z - ((scratchVector->z * g_pYasuiLimitGreatGospelCameraTrack->distance) >> 12);
                break;
            case SUMMON_CAMERA_MOVE_EASED:
                g_pYasuiLimitGreatGospelCameraTrack->distance += g_pYasuiLimitGreatGospelCameraTrack->delta;
                easedVal = g_pYasuiLimitGreatGospelCameraTrack->distance;
                for (easeIdx = 0; easeIdx < g_pYasuiLimitGreatGospelCameraTrack->easing; easeIdx++)
                    easedVal = SinFixed(easedVal / 4);
                g_pYasuiLimitGreatGospelCameraTrack->position.x = g_pYasuiLimitGreatGospelCameraTrack->base.x + ((g_pYasuiLimitGreatGospelCameraTrack->velocity.x * easedVal) >> 12);
                g_pYasuiLimitGreatGospelCameraTrack->position.y = g_pYasuiLimitGreatGospelCameraTrack->base.y + ((g_pYasuiLimitGreatGospelCameraTrack->velocity.y * easedVal) >> 12);
                g_pYasuiLimitGreatGospelCameraTrack->position.z = g_pYasuiLimitGreatGospelCameraTrack->base.z + ((g_pYasuiLimitGreatGospelCameraTrack->velocity.z * easedVal) >> 12);
                break;
            }
            g_pYasuiLimitGreatGospelCameraTrack->frames--;
            g_pYasuiLimitGreatGospelCameraTrack = &g_BattleLimitGreatGospelCameraFocus;
            g_pYasuiLimitGreatGospelCameraOther = &g_YasuiLimitGreatGospelCameraEye;
        }
    }
    if (taskPtr->matrix) {
        if (g_YasuiLimitGreatGospelCameraEye.mode != SUMMON_CAMERA_HOLD_OUTPUT) {
            SetRotMatrix((void *)taskPtr->matrix);
            SetTransMatrix((void *)taskPtr->matrix);
            if (g_YasuiLimitGreatGospelCameraEye.actor == -1) {
                RotTransPoint(&g_YasuiLimitGreatGospelCameraEye.position, wideVec, &bits);
                g_BattleCameraPosition.cameraPosX = wideVec[0];
                g_BattleCameraPosition.cameraPosY = wideVec[1];
                g_BattleCameraPosZ = wideVec[2];
            } else {
                RotateSVectorByInstalledMatrix(&g_YasuiLimitGreatGospelCameraEye.position, wideVec);
                if (g_YasuiLimitGreatGospelCameraEye.bone != -1) {
                    Battle_GetBoneWorldPos(g_YasuiLimitGreatGospelCameraEye.actor, g_YasuiLimitGreatGospelCameraEye.bone, (short *)scratchVector);
                } else {
                    scratchVector->x = g_BattleActorRecords[g_YasuiLimitGreatGospelCameraEye.actor].posX;
                    scratchVector->y = g_BattleActorRecords[g_YasuiLimitGreatGospelCameraEye.actor].posY;
                    scratchVector->z = g_BattleActorRecords[g_YasuiLimitGreatGospelCameraEye.actor].posZ;
                }
                g_BattleCameraPosition.cameraPosX = wideVec[0] + scratchVector->x;
                g_BattleCameraPosition.cameraPosY = wideVec[1] + scratchVector->y;
                g_BattleCameraPosZ = wideVec[2] + scratchVector->z;
                SetRotMatrix((void *)taskPtr->matrix);
                SetTransMatrix((void *)taskPtr->matrix);
            }
        }
        if (g_BattleLimitGreatGospelCameraFocus.mode != SUMMON_CAMERA_HOLD_OUTPUT) {
            if (g_BattleLimitGreatGospelCameraFocus.actor == -1) {
                RotTransPoint(&g_BattleLimitGreatGospelCameraFocus.position, wideVec, &bits);
                g_BattleCameraFocalPoint.focalPointX = wideVec[0];
                g_BattleCameraFocalPoint.focalPointY = wideVec[1];
                g_BattleCameraFocusZ = wideVec[2];
            } else {
                RotateSVectorByInstalledMatrix(&g_BattleLimitGreatGospelCameraFocus.position, wideVec);
                if (g_BattleLimitGreatGospelCameraFocus.bone != -1) {
                    Battle_GetBoneWorldPos(g_BattleLimitGreatGospelCameraFocus.actor, g_BattleLimitGreatGospelCameraFocus.bone, (short *)scratchVector);
                } else {
                    scratchVector->x = g_BattleActorRecords[g_BattleLimitGreatGospelCameraFocus.actor].posX;
                    scratchVector->y = g_BattleActorRecords[g_BattleLimitGreatGospelCameraFocus.actor].posY;
                    scratchVector->z = g_BattleActorRecords[g_BattleLimitGreatGospelCameraFocus.actor].posZ;
                }
                g_BattleCameraFocalPoint.focalPointX = wideVec[0] + scratchVector->x;
                g_BattleCameraFocalPoint.focalPointY = wideVec[1] + scratchVector->y;
                g_BattleCameraFocusZ = wideVec[2] + scratchVector->z;
            }
        }
    } else {
        if (g_YasuiLimitGreatGospelCameraEye.mode != SUMMON_CAMERA_HOLD_OUTPUT) {
            *(int *)&g_BattleCameraPosition = *(int *)&g_YasuiLimitGreatGospelCameraEye.position;
            *(int *)&g_BattleCameraPosZ = *(int *)&g_YasuiLimitGreatGospelCameraEye.position.z;
        }
        if (g_BattleLimitGreatGospelCameraFocus.mode != SUMMON_CAMERA_HOLD_OUTPUT) {
            *(int *)&g_BattleCameraFocalPoint = *(int *)&g_BattleLimitGreatGospelCameraFocus.position;
            *(int *)&g_BattleCameraFocusZ = *(int *)&g_BattleLimitGreatGospelCameraFocus.position.z;
        }
    }
}

/*
 * Reads a 16-bit operand from the camera script command stream.
 */
// FUNCTION: FF7 0x00474c04
short __cdecl BattleFx_GreatGospelReadCameraScriptOperand(short **scriptPtr)
{
    int val;

    val = **scriptPtr;
    (*scriptPtr)++;
    if (val < 0) {
        val = (&g_YasuiLimitGreatGospelTaskStatePtrs.limitEvaCameraOperandWord)[-val];
    }
    return (short)val;
}

/*
 * Clears the active particle callback table.
 */
// FUNCTION: FF7 0x00474c3e
void __cdecl BattleFx_GreatGospelClearParticleTable(void)
{
    int i;

    for (i = 0; i < 0x12C; i++) {
        g_YasuiLimitEvaParticleCallbacks[i] = 0;
    }
}

/*
 * Iterates active particle pool entries, invoking each callback and clearing retired particles.
 */
// FUNCTION: FF7 0x00474c71
void __cdecl BattleFx_GreatGospelParticlePoolTask(void)
{
    int activeCount;
    BattleTaskSlot *task;
    int particleIdx;

    task = BATTLE_CURRENT_TASK_SLOT;
    activeCount = 0;
    for (particleIdx = 0; particleIdx < 0x12C; particleIdx++) {
        if (g_YasuiLimitEvaParticleCallbacks[particleIdx] != 0) {
            g_YasuiLimitEvaParticleCallbacks[particleIdx](particleIdx * 0x14 + (int)&g_YasuiLimitGreatGospelParticleRecords);
            if (g_YasuiLimitGreatGospelParticleRecords[particleIdx].state == -1) {
                g_YasuiLimitEvaParticleCallbacks[particleIdx] = 0;
            } else {
                activeCount++;
            }
        }
    }
    if (activeCount == 0 && g_BattleSecondaryTaskActiveCount <= 1) {
        task->ownerSlot = BATTLE_TASK_FREE;
    }
}

/*
 * Master timeline task managing effect phases, sound effects, emitters, and models.
 */
// FUNCTION: FF7 0x00474d1c
void __cdecl BattleFx_GreatGospelTimelineTask(void)
{
    int angle;
    int rad;
    int frame;
    int spawnIdx;
    BattleTaskSlot *task;
    BattleFxEvaTimeline *child;
    task = BATTLE_CURRENT_TASK_SLOT;
    MultiplyMatrix(&g_BattleCameraTransform, &g_YasuiLimitGreatGospelModelMatrix, &g_YasuiLimitGreatGospelViewMatrix);
    if (g_BattleIsPaused != 0) {
        return;
    }
    frame = task->frameCounter;
    if (frame < 0xE) {
        if (frame == 0) {
            g_BattleFxTimelineState.red = 0;
            g_BattleFxTimelineState.channel1 = 0;
            g_BattleFxTimelineState.channel2 = 0;
            Battle_StartFixedPointRamp(0x800, 0xA);
        }
        if (frame == 0) {
            child = (BattleFxEvaTimeline *)BATTLE_NEW_TASK_SLOT(BattleFx_GreatGospelFallingStreakEmitterTask);
        }
        if (frame == 0) {
            Battle_DispatchSfxOpcodeDirect(SOUND_SFX_PLAY_1, 0x40, 0x242);
        }
    } else {
        frame -= 0xE;
        if (frame < 8) { /* empty first arm: lib/codegen.h */
        } else {
            frame -= 8;
            if (frame < 8) { /* empty first arm: lib/codegen.h */
            } else {
                frame -= 8;
                if (frame < 0xA) { /* empty first arm: lib/codegen.h */
                } else {
                    frame -= 0xA;
                    if (frame < 0x19) {
                        if (frame == 0) {
                            child = (BattleFxEvaTimeline *)BATTLE_NEW_TASK_SLOT(BattleFx_GreatGospelDiscardedColorScaleRampTask);
                            Battle_StartFixedPointRamp(0, 0x19);
                        }
                    } else {
                        frame -= 0x19;
                        if (frame < 0xA) {
                            if (frame == 0) {
                                child = (BattleFxEvaTimeline *)BATTLE_NEW_TASK_SLOT(BattleFx_GreatGospelSteppedModelTask);
                            }
                        } else {
                            frame -= 0xA;
                            if (frame < 5) { /* empty first arm: lib/codegen.h */
                            } else {
                                frame -= 5;
                                if (frame < 5) { /* empty first arm: lib/codegen.h */
                                } else {
                                    frame -= 5;
                                    if (frame < 0x14) { /* empty first arm: lib/codegen.h */
                                    } else {
                                        frame -= 0x14;
                                        if (frame < 0xA) {
                                            if (frame == 0) {
                                                child = (BattleFxEvaTimeline *)BATTLE_NEW_TASK_SLOT(BattleFx_GreatGospelSpinningModelTask);
                                                for (spawnIdx = 0; spawnIdx < 3; spawnIdx++) {
                                                    child = (BattleFxEvaTimeline *)BATTLE_NEW_TASK_SLOT(BattleFx_GreatGospelSpiralingModelTask);
                                                    child->spiral.index = rand() % 0xA;
                                                    angle = (spawnIdx << 0xC) / 3 + rand() % 0x155;
                                                    rad = (UNFOLDED(0) ? 0x1F4 : rand() % 0x64 + 0x190);
                                                    child->spiral.radius = rad;
                                                    child->spiral.offsetY = (UNFOLDED(0) ? 0xFFFFDECC : rand() % 0x5DC - 0x2710);
                                                    child->spiral.velocityY = rand() % 0x28 - 0x14;
                                                    child->spiral.rotX = 0x200;
                                                    child->spiral.angle = angle;
                                                    child->spiral.rotZ = 0;
                                                    child->spiral.angleVelocity = (rand() % 64) - 0x20;
                                                }
                                                child = (BattleFxEvaTimeline *)BATTLE_NEW_TASK_SLOT(BattleFx_GreatGospelGrowingFadeModelEmitterTask);
                                                for (spawnIdx = 0; spawnIdx < 5; spawnIdx++) {
                                                    child = (BattleFxEvaTimeline *)BATTLE_NEW_TASK_SLOT(BattleFx_GreatGospelExpandingFadeModelTask);
                                                    child->particle.posX = 0;
                                                    child->particle.posY = 0xFDA8;
                                                    child->particle.posZ = 0x1000;
                                                    child->particle.velocityX = spawnIdx * 0x3E8 / 5;
                                                    child->particle.velocityY = spawnIdx * 0x4B0 / 5;
                                                    child->particle.velocityZ = UNFOLDED(0) / 5;
                                                    child->particle.scale = (UNFOLDED(0) ? 0x400 : rand() % 0x300 + 0x100);
                                                }
                                            }
                                        } else {
                                            frame -= 0xA;
                                            if (frame < 0x14) { /* empty first arm: lib/codegen.h */
                                            } else {
                                                frame -= 0x14;
                                                if (frame < 0x1E) {
                                                    if (frame == 0) {
                                                        child = (BattleFxEvaTimeline *)BATTLE_NEW_TASK_SLOT(BattleFx_GreatGospelWideGrowingFadeModelEmitterTask);
                                                        Battle_CreateBitPatternCallbackTask(g_YasuiLimitGreatGospelEffectTargetMask, 0, 0, BattleFx_GreatGospelSpawnPerTarget);
                                                    }
                                                } else {
                                                    g_BattleStageHideFlags = 0;
                                                    task->ownerSlot = BATTLE_TASK_FREE;
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    (task->frameCounter)++;
}

/*
 * Emitter task spawning falling streak particles across the battlefield.
 */
// FUNCTION: FF7 0x0047518a
void __cdecl BattleFx_GreatGospelFallingStreakEmitterTask(void)
{
    int frameIndex;
    int padSlot[2]; /* Unreferenced stack padding preserved for VC5 /Od frame size (see lib/codegen.h). */
    BattleFxLimitStardustRayQuadState *taskPtr;
    int shift;
    int randX8;
    BattleFxGreatGospelStreakParticle *streak;
    int emitAmount;
    int ratio;
    int valueZ;

    taskPtr = (BattleFxLimitStardustRayQuadState *)BATTLE_CURRENT_TASK_SLOT;
    if (g_BattleIsPaused != 0) {
        return;
    }
    frameIndex = taskPtr->index;
    if (frameIndex < 0x16) {
        ratio = (frameIndex << 0xC) / 0x16;
        emitAmount = ratio << 0xC >> 0xC;
        shift = 0;
    } else {
        frameIndex -= 0x16;
        if (frameIndex < 0x12) {
            emitAmount = 0x1000;
            shift = 0;
        } else {
            frameIndex -= 0x12;
            if (frameIndex < 0x14) {
                ratio = (frameIndex << 0xC) / 0x14;
                emitAmount = 0x1000 - ratio << 0xC >> 0xC;
                shift = 1;
            } else {
                taskPtr->ownerSlot = BATTLE_TASK_FREE;
                return;
            }
        }
    }
    emitAmount = (emitAmount * taskPtr->index & 0xFF) + emitAmount;
    while (emitAmount >= 0x100) {
        streak = (BattleFxGreatGospelStreakParticle *)(BattleFx_GreatGospelClaimParticleRecord((int)BattleFx_GreatGospelFallingStreakTask));
        if (DEAD_IN_RETAIL != 0) {
            randX8 = 0x7D0;
        } else {
            randX8 = rand() % 0xFA0 - 0x7D0;
        }
        streak->posX = randX8 >> shift;
        streak->posY = rand() % 0x1F4 - 0x1388;
        if (DEAD_IN_RETAIL != 0) {
            valueZ = 0x7D0;
        } else {
            valueZ = rand() % 0xFA0 - 0x7D0;
        }
        streak->posZ = valueZ >> shift;
        streak->velocityX = 0;
        streak->velocityY = 0x1F4;
        streak->velocityZ = 0xFFCE;
        emitAmount -= 0x100;
    }
    (taskPtr->index)++;
}

/*
 * Claims a free slot in the particle callback table.
 */
// FUNCTION: FF7 0x00475348
int __cdecl BattleFx_GreatGospelClaimParticleRecord(int callback)
{
    int i;

    for (i = 0; i < 0x12C; i++) {
        if (g_YasuiLimitEvaParticleCallbacks[i] == 0) {
            g_YasuiLimitEvaParticleCallbacks[i] = (void (__cdecl *)(int))callback;
            g_YasuiLimitGreatGospelParticleRecords[i].state = 0;
            g_YasuiLimitGreatGospelParticleRecords[i].frameIndex = 0;
            return i * 0x14 + (int)&g_YasuiLimitGreatGospelParticleRecords;
        }
    }
    return 0;
}

/*
 * Updates a falling light streak particle until it impacts the ground.
 */
// FUNCTION: FF7 0x004753b4
void __cdecl BattleFx_GreatGospelFallingStreakTask(BattleFxMeshShardSlot *particleRecord)
{
    BattleFxGreatGospelStreakParticle *impact;
    BattleFxGreatGospelRenderStateBlock *packet;

    if ((g_YasuiLimitGreatGospelStreakBlockReady & 1) == 0) {
        g_YasuiLimitGreatGospelStreakBlockReady |= 1;
        g_YasuiLimitGreatGospelTaskStatePtrs.streakState = (BattleFxGreatGospelStreakState *)Gfx_GetPsxScratchpadPtr(0);
    }
    g_YasuiLimitGreatGospelTaskStatePtrs.streakState->posX = particleRecord->x + particleRecord[1].x;
    g_YasuiLimitGreatGospelTaskStatePtrs.streakState->posY = particleRecord->y + particleRecord[1].y;
    g_YasuiLimitGreatGospelTaskStatePtrs.streakState->posZ = particleRecord[1].z + particleRecord[2].z;
    if (g_YasuiLimitGreatGospelTaskStatePtrs.streakState->posY > 0) {
        impact = (BattleFxGreatGospelStreakParticle *)(BattleFx_GreatGospelClaimParticleRecord((int)BattleFx_GreatGospelStreakImpactSpriteTask));
        impact->posX = g_YasuiLimitGreatGospelTaskStatePtrs.streakState->posX;
        impact->posY = 0;
        impact->posZ = g_YasuiLimitGreatGospelTaskStatePtrs.streakState->posZ;
        particleRecord->z = BATTLE_TASK_FREE;
    } else {
        SetRotMatrix(&g_YasuiLimitGreatGospelViewMatrix);
        SetTransMatrix(&g_YasuiLimitGreatGospelViewMatrix);
        RefreshGlobalTransformState();
        packet = (BattleFxGreatGospelRenderStateBlock *)Gfx_GetPsxPacketScratchPtr();
        g_YasuiLimitGreatGospelTaskStatePtrs.streakState->depth = Gfx_TransformTriangleReturnDepthAlt((char *)particleRecord + 4, (SVECTOR *)g_YasuiLimitGreatGospelTaskStatePtrs.streakState, (SVECTOR *)g_YasuiLimitGreatGospelTaskStatePtrs.streakState, &g_YasuiLimitGreatGospelTaskStatePtrs.streakState->pad_0C, &g_YasuiLimitGreatGospelTaskStatePtrs.streakState->flags);
        if ((g_YasuiLimitGreatGospelTaskStatePtrs.streakState->flags & 0x60000) == 0) {
            packet->tag = 0x4000000;
            packet->color0 = 0x52202020;
            packet->color1 = 0x606060;
            Gfx_DrawPsxPrimitive(packet);
            g_YasuiLimitGreatGospelDrawListHead = (int)packet;
        }
        if (g_BattleIsPaused == 0) {
            particleRecord->x = g_YasuiLimitGreatGospelTaskStatePtrs.streakState->posX;
            particleRecord->y = g_YasuiLimitGreatGospelTaskStatePtrs.streakState->posY;
            particleRecord[1].z = g_YasuiLimitGreatGospelTaskStatePtrs.streakState->posZ;
        }
    }
}

/*
 * Animates an impact splash sprite on the ground after streak landing.
 */
// FUNCTION: FF7 0x00475568
